import { askPersistOnce } from './persist.js';
import { migrateSkeletonUrns } from './temporal.js';

const INDEX = 'sources-index.json';
// READ MIGRATION of the index FILE NAME. The file was `bronnen-index.json`
// until 24 Sep 2026, and it is stored user state: an index written by an older
// version has to keep pointing at its OPFS copies and working files. So a read
// falls back to the old name, and the first write after that lands on the new
// one — after which the old file is removed, so the fallback fires once per
// browser and never again. `src/model/test/opfs.test.mjs` pins both halves.
const INDEX_BEFORE_24_SEP_2026 = 'bronnen-index.json';
let testRoot = null;

export function _setRootForTest(root) { testRoot = root; }

export function opfsAvailable() {
  return !!testRoot || !!(globalThis.navigator && navigator.storage && navigator.storage.getDirectory);
}
async function root() { return testRoot || navigator.storage.getDirectory(); }

async function rawWrite(name, text) {
  const h = await (await root()).getFileHandle(name, { create: true });
  const w = await h.createWritable();
  await w.write(text);
  await w.close();
}

export async function opfsWrite(name, text) {
  // Not awaited: a browser that prompts would otherwise stall the autosave that
  // called this, and the grant is about the NEXT eviction sweep, not this write.
  void askPersistOnce();
  await rawWrite(name, text);
}

export async function opfsRead(name) {
  try {
    const h = await (await root()).getFileHandle(name);
    return migrateSkeletonUrns(await (await h.getFile()).text());
  } catch (e) {
    if (e && e.name === 'NotFoundError') return null;
    throw e;
  }
}

export async function opfsDelete(name) {
  try { await (await root()).removeEntry(name); }
  catch {  }
}

// READ MIGRATION of the whole stored index shape. Four keys were Dutch before
// the rename: the copy register `kopieen`, the working-file list
// `werkbestanden`, and inside an entry `bestand`/`naam`. This is stored USER
// STATE — an index written by an older version must keep pointing at its OPFS
// copies and working files — so every old key keeps being read, and the new key
// wins wherever both are present. Writing only ever uses the new shape.
function migrateEntry(e) {
  const out = { ...e };
  if (out.file === undefined && out.bestand !== undefined) out.file = out.bestand;
  if (out.name === undefined && out.naam !== undefined) out.name = out.naam;
  delete out.bestand;
  delete out.naam;
  return out;
}

function migrateIndex(p) {
  const copiesRaw = p.copies || p.kopieen || {};
  const copies = Object.fromEntries(
    Object.entries(copiesRaw).map(([url, entry]) => [url, migrateEntry(entry || {})]),
  );
  const workingRaw = p.workingFiles || p.werkbestanden || [];
  return {
    copies,
    workingFiles: (Array.isArray(workingRaw) ? workingRaw : []).map((w) => migrateEntry(w || {})),
    editSource: p.editSource || null,
  };
}

export async function readIndex() {
  const raw = await opfsRead(INDEX) ?? await opfsRead(INDEX_BEFORE_24_SEP_2026);
  if (!raw) return migrateIndex({});
  try {
    return migrateIndex(JSON.parse(raw));
  } catch {
    return migrateIndex({});
  }
}

export async function writeIndex(index) {
  // rawWrite, not opfsWrite: bookkeeping is not a working file, so it does not
  // trigger the persistent-storage request.
  await rawWrite(INDEX, JSON.stringify(index, null, 2));
  // The old file would otherwise keep shadowing nothing forever, and a reader
  // that only knew the old name would drift away from the truth.
  await opfsDelete(INDEX_BEFORE_24_SEP_2026);
}
