import { createSignal } from 'solid-js';
import { graphForSource } from '../model-boundary.js';
import { vocabularyName } from '../model/default-corpus.js';
import type { Source } from '../model-boundary.js';
import {
  readIndex, opfsAvailable, opfsDelete, opfsRead, opfsWrite, writeIndex,
} from '../model/opfs.js';
import { setPersistReporter } from '../model/persist.js';
import {
  lazyLoadedNodes, sources, endpoint, errors, graph, reloadSources,
  registerSourcePreprocessing, setSourcesList,
} from './corpus.js';
import { view, setNotice, setView } from './view.js';

export interface SourceInput {
  name: string;
  url?: string;
  content?: string;
  format?: string;
  fromSparql?: boolean;
}

export interface SourceEdit extends SourceInput {
  graph: string;
  kind: 'ttl' | 'sparql';
  mode: 'read' | 'readwrite';
  position: number;
  opfs: string | null;
  updateUrl?: string;
  vocab: boolean;
}

interface SourceIndex {
  copies: Record<string, { file: string }>;
  workingFiles: { name: string; file: string }[];
  editSource?: string | null;
}

const EMPTY: SourceIndex = { copies: {}, workingFiles: [], editSource: null };

// An endpoint corpus passes no source preprocessing at all, so without a deadline
// a remembered edit source would keep the recovery window open for ever.
const RECOVERY_DEADLINE_MS = 5000;

const OPFS_LIMIT_MS = 5000;

const [index, setIndex] = createSignal<SourceIndex>(EMPTY);
const [editSourceGraph, setEditSourceGraph] = createSignal<string | null>(null);
const [endpointUpdateUrl, setEndpointUpdateUrl] = createSignal<string | null>(null);
const [recoveryBusy, setRecoveryBusy] = createSignal(false);
let recoveryRunning = false;

export { editSourceGraph, endpointUpdateUrl, recoveryBusy };

export function opfsOn(): boolean { return opfsAvailable(); }

interface Edges {
  flush: (source?: SourceEdit | null) => Promise<void>;
  download: (name: string, text: string, mime: string) => void;
  fetchText: (url: string) => Promise<string | null>;
  report: (key: string, vars?: Record<string, unknown>) => void;
}

const DEFAULT: Edges = {
  flush: async () => {},
  download: (name, text, mime) => {
    if (typeof Blob === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) return;
    const url = URL.createObjectURL(new Blob([text], { type: mime }));
    const a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  },
  fetchText: async (url) => {
    try {
      const r = await fetch(url);
      return r.ok ? await r.text() : null;
    } catch { return null; }
  },
  report: (key, vars) => setNotice(key, vars),
};

let edges: Edges = { ...DEFAULT };

export function attachFlush(fn: Edges['flush'] | null): void {
  edges.flush = fn || DEFAULT.flush;
}

export function _setForTest(part: Partial<Edges>): void {
  edges = { ...DEFAULT, ...part };
}

export async function _restoreForTest(): Promise<void> {
  setEditSourceGraph(null);
  setEndpointUpdateUrl(null);
  setRecoveryBusy(false);
  recoveryRunning = false;
  setIndex(EMPTY);
  await loadIndex();
}

export async function loadIndex(): Promise<SourceIndex> {
  if (!opfsAvailable()) { setIndex(EMPTY); return EMPTY; }
  try {
    const i = await readIndex() as SourceIndex;
    setIndex(i);
    return i;
  } catch { setIndex(EMPTY); return EMPTY; }
}

async function write(i: SourceIndex): Promise<void> {
  await writeIndex(i);
  setIndex({
    copies: { ...i.copies },
    workingFiles: [...i.workingFiles],
    editSource: i.editSource ?? null,
  });
}

// Keys on url or name and never on the graph: a url-less source has a POSITIONAL
// graph, so its entry would point at nothing once a source before it disappears.
export function copyFilename(source: { url?: string; name: string }): string {
  const base = String(source.url || source.name || 'source').replace(/[^a-z0-9.-]/gi, '_');
  // , not : NEW copies only. An existing local copy keeps working,
  // because a read resolves the file name from the stored index entry
  // () and never recomputes it — so no migration is owed.
  return 'copy-' + base.slice(-120);
}

function sourceKey(s: { url?: string; name?: string }): string {
  return s.url || 'name:' + (s.name || '');
}

async function rememberEditSource(key: string | null): Promise<void> {
  if (!opfsAvailable()) return;
  try {
    const i = await readIndex() as SourceIndex;
    if ((i.editSource ?? null) === key) return;
    await write({ ...i, editSource: key });
  } catch {  }
}

export function enrichSources(
  list: readonly SourceInput[] | null,
  sourceIndex: SourceIndex | null,
  editable: string | null,
): SourceEdit[] {
  const i = sourceIndex || EMPTY;
  let alreadyGiven = false;
  return (list || []).map((s, position) => {
    const graph = String(graphForSource(s, position));
    const opfs = s.url
      ? (i.copies[s.url]?.file ?? null)
      : (i.workingFiles.find((w) => w.name === s.name)?.file ?? null);
    const edited = (): 'read' | 'readwrite' => {
      if (alreadyGiven || s.fromSparql || graph !== editable) return 'read';
      alreadyGiven = true;
      return 'readwrite';
    };
    return {
      ...s,
      graph,
      position,
      kind: s.fromSparql ? 'sparql' : 'ttl',
      mode: edited(),
      opfs,
      vocab: !!vocabularyName(s.url),
    };
  });
}

export function sourceRows(): SourceEdit[] {
  return enrichSources(sources(), index(), editSourceGraph());
}

export function editSource(): SourceEdit | null {
  const g = editSourceGraph();
  if (!g) return null;
  const hit = sourceRows().find((r) => r.graph === g && !r.fromSparql);
  if (hit) return hit;
  const ep = endpoint();
  const url = endpointUpdateUrl();
  if (ep && url && String(graphForSource({ url: ep }, 0)) === g) {
    return {
      name: ep, url: ep, graph: g, position: -1, kind: 'sparql', mode: 'readwrite',
      opfs: null, updateUrl: url, vocab: false,
    };
  }
  return null;
}

function withoutFormatting(text: string): string {
  return String(text || '')
    .replace(/@prefix\s+[^\s:]*:\s*<[^>]*>\s*\./gi, ' ')
    .replace(/@base\s+<[^>]*>\s*\./gi, ' ')
    .replace(/^[ \t]*PREFIX\s+[^\s:]*:\s*<[^>]*>[ \t]*$/gim, ' ')
    .replace(/^[ \t]*BASE\s+<[^>]*>[ \t]*$/gim, ' ')
    .split('\n')
    .filter((r) => !/^\s*#/.test(r))
    .join('\n')
    .trim();
}

export function copyEmptiesSource(exportText: string, sourceContent: string): boolean {
  return withoutFormatting(exportText) === '' && withoutFormatting(sourceContent) !== '';
}

async function serialisatie(): Promise<{
  exportTurtle: (store: unknown, options: { graph?: string }) => string;
  exportJsonLd: (store: unknown, options: { graph?: string }) => string;
  unnamedPolicies: (store: unknown, graphIri?: string) => unknown[];
}> {
  return await import('../model/edit.js') as never;
}

export async function makeEditable(source: SourceEdit): Promise<void> {
  if (!source) return;
  const previous = editSource();
  if (previous && previous.graph !== source.graph) await edges.flush(previous);
  if (source.opfs) {
    setEditSourceGraph(source.graph);
    await rememberEditSource(sourceKey(source));
    return;
  }
  if (!opfsAvailable()) { edges.report('src.opfsOff'); return; }
  const g = graph();
  if (!g) return;
  const { exportTurtle } = await serialisatie();
  const file = copyFilename(source);
  const ttl = exportTurtle(g, { graph: source.graph });
  if (copyEmptiesSource(ttl, source.content || '')) {
    edges.report('src.copyEmpty', { source: source.name || source.url || file });
    return;
  }
  try {
    await opfsWrite(file, ttl);
    const i = await readIndex() as SourceIndex;
    if (source.url) i.copies[source.url] = { file: file };
    else if (!i.workingFiles.some((w) => w.file === file)) {
      i.workingFiles.push({ name: source.name, file: file });
    }
    i.editSource = sourceKey(source);
    await write(i);
  } catch (e) {
    edges.report('src.opfsError', { error: (e as Error).message });
    return;
  }
  setSourcesList(sources().map((s, i) => (i === positionOf(source)
    ? { ...s, content: ttl, format: 'turtle' } : s)));
  setEditSourceGraph(source.graph);
  edges.report('src.localCreated', { source: source.name || source.url || file });
}

export async function stopEditing(): Promise<void> {
  const current = editSource();
  if (current) await edges.flush(current);
  setEditSourceGraph(null);
  await rememberEditSource(null);
}

function positionOf(source: SourceEdit): number {
  const rows = sourceRows();
  if (rows[source.position]?.graph === source.graph) return source.position;
  return rows.findIndex((r) => r.graph === source.graph);
}

export async function restoreOriginal(source: SourceEdit): Promise<void> {
  if (!source) return;
  try {
    await edges.flush(source);
    if (source.opfs) await opfsDelete(source.opfs);
    if (opfsAvailable()) await write(withoutTraces(await readIndex() as SourceIndex, source));
  } catch (e) {
    edges.report('src.opfsError', { error: (e as Error).message });
    return;
  }
  await forgetEditSource(source);
  const verse = source.url ? await edges.fetchText(source.url) : null;
  const position = positionOf(source);
  await reload(sources().map((s, i) => (i === position
    ? { ...s, content: verse ?? s.content, format: verse ? formaatVan(source.url!, verse) : s.format }
    : s)));
}

function formaatVan(url: string, content: string): string {
  return /^\s*[[{]/.test(content) || /\.jsonld?$/i.test(url) ? 'jsonld' : 'turtle';
}

async function forgetEditSource(source: SourceEdit): Promise<void> {
  if (editSourceGraph() !== source.graph) return;
  setEditSourceGraph(null);
  await rememberEditSource(null);
}

function withoutTraces(i: SourceIndex, source: SourceEdit): SourceIndex {
  const copies = { ...i.copies };
  if (source.url) delete copies[source.url];
  const key = sourceKey(source);
  return {
    copies,
    workingFiles: i.workingFiles.filter((w) => w.file !== source.opfs && w.name !== source.name),
    editSource: (i.editSource ?? null) === key ? null : (i.editSource ?? null),
  };
}

export async function makeWorkFile(): Promise<void> {
  if (!opfsAvailable()) { edges.report('src.opfsOff'); return; }
  const stempel = new Date().toISOString().replace(/[:.]/g, '-');
  const name = 'werk-' + stempel + '.ttl';
  try {
    await opfsWrite(name, '');
    const i = await readIndex() as SourceIndex;
    i.workingFiles.push({ name: name, file: name });
    i.editSource = sourceKey({ name: name });
    await write(i);
  } catch (e) {
    edges.report('src.opfsError', { error: (e as Error).message });
    return;
  }
  const list = sources();
  const graph = String(graphForSource({}, list.length));
  await reload([...list, { name: name, content: '', format: 'turtle' }]);
  setEditSourceGraph(graph);
  reportSideLoaded();
}

export function addSourceByAddress(address: string): 'added' | 'duplicate' | 'empty' {
  const url = String(address || '').trim();
  if (!url) return 'empty';
  const inStore = new Set(
    sources().filter((b) => !b.fromSparql && b.url).map((b) => String(b.url)),
  );
  if (inStore.has(url) || endpoint() === url) return 'duplicate';
  declareSources({ add: url });
  return 'added';
}

function declareSources(options: { add?: string; remove?: string } = {}): void {
  const { add, remove } = options;
  const legacy = new Set(view.ttl.filter((u) => u !== remove));
  const list: string[] = [];
  const seen = new Set<string>();
  const set = (u: string): void => {
    if (u === remove || seen.has(u) || legacy.has(u) || vocabularyName(u)) return;
    seen.add(u);
    list.push(u);
  };
  for (const b of sources()) if (!b.fromSparql && b.url) set(String(b.url));
  const broken = new Set(errors().map((f) => f.url).filter(Boolean) as string[]);
  for (const u of view.src) if (broken.has(u)) set(u);
  if (add) set(add);
  const patch: { src: string[]; ttl?: string[] } = { src: list };
  if (remove && view.ttl.includes(remove)) patch.ttl = [...legacy];
  setView(patch);
}

function isInTheUrl(source: SourceEdit): boolean {
  return !!source.url && (view.src.includes(source.url) || view.ttl.includes(source.url));
}

export function lazyLoadedNotice(): { n: number; ep: string } | null {
  const list = lazyLoadedNodes();
  if (!list.length) return null;
  return { n: list.length, ep: list[0].ep || endpoint() || '' };
}

function reportSideLoaded(): void {
  const m = lazyLoadedNotice();
  if (m) edges.report('src.lazyLoadedNote', { n: m.n, ep: m.ep });
}

export async function removeSource(source: SourceEdit): Promise<void> {
  if (!source) return;
  await ruimOpfsOp(source);
  await forgetEditSource(source);
  const position = positionOf(source);
  const rest = sources().filter((_s, i) => i !== position);
  if (isInTheUrl(source)) {
    setSourcesList(rest);
    declareSources({ remove: source.url });
    return;
  }
  await reload(rest);
}

async function ruimOpfsOp(source: SourceEdit): Promise<void> {
  if (!source.opfs || !opfsAvailable()) return;
  try {
    await edges.flush(source);
    await opfsDelete(source.opfs);
    await write(withoutTraces(await readIndex() as SourceIndex, source));
  } catch (e) {
    edges.report('src.opfsError', { error: (e as Error).message });
  }
}

// A draft may never look like a valid file without saying so: the ODRL IM
// requires a uid on every Policy, and a nameless one cannot carry it.
export function warnUnnamed(
  count: (store: unknown, graphIri?: string) => unknown[], g: unknown, graphIri: string,
): void {
  const n = count(g, graphIri).length;
  if (!n) return;
  edges.report(n === 1 ? 'export.noId.one' : 'export.noId', { n });
}

export async function downloadSource(source: SourceEdit, formaat: 'ttl' | 'jsonld'): Promise<void> {
  const g = graph();
  if (!source || !g) return;
  await edges.flush(source);
  const { exportTurtle, exportJsonLd, unnamedPolicies } = await serialisatie();
  warnUnnamed(unnamedPolicies, g, source.graph);
  const base = String(source.name || 'source').split(/[\\/]/).pop() || 'source';
  if (formaat === 'jsonld') {
    edges.download(base.replace(/\.(ttl|turtle|nt|json|jsonld)$/i, '') + '.jsonld',
      exportJsonLd(g, { graph: source.graph }), 'application/ld+json');
    return;
  }
  edges.download(/\.(ttl|turtle)$/i.test(base) ? base : base + '.ttl',
    exportTurtle(g, { graph: source.graph }), 'text/turtle');
}

export function updateUrlProposal(ep: string | null): string {
  return String(ep || '').replace(/\/(sparql|query)$/, '/update');
}

export async function makeEndpointEditable(updateUrl: string): Promise<void> {
  const ep = endpoint();
  if (!ep || !updateUrl) return;
  setEndpointUpdateUrl(updateUrl);
  setEditSourceGraph(String(graphForSource({ url: ep }, 0)));
  await rememberEditSource(null);
}

export async function lockEndpoint(): Promise<void> {
  const ep = endpoint();
  if (ep && editSourceGraph() === String(graphForSource({ url: ep }, 0))) {
    const current = editSource();
    if (current) await edges.flush(current);
    setEditSourceGraph(null);
    await rememberEditSource(null);
  }
  setEndpointUpdateUrl(null);
}

export async function withOpfsSources(list: readonly Source[]): Promise<Source[]> {
  if (!opfsAvailable()) { setRecoveryBusy(false); return [...list]; }
  recoveryRunning = true;
  let timer: ReturnType<typeof setTimeout> | null = null;
  const TOO_SLOW = Symbol('opfs too slow');
  try {
    const limit = new Promise<typeof TOO_SLOW>((r) => {
      timer = setTimeout(() => r(TOO_SLOW), OPFS_LIMIT_MS);
    });
    const out = await Promise.race([readOpfsSources(list), limit]);
    if (out === TOO_SLOW) {
      edges.report('src.opfsSlow', { sec: Math.round(OPFS_LIMIT_MS / 1000) });
      return [...list];
    }
    return out;
  } finally {
    if (timer !== null) clearTimeout(timer);
    recoveryRunning = false;
    setRecoveryBusy(false);
  }
}

async function readOpfsSources(list: readonly Source[]): Promise<Source[]> {
  const i = await loadIndex();
  const out: Source[] = [];
  const seen = new Set<string>();
  const fresh = (s: { url?: string; name: string }): boolean => {
    const key = s.url || 'name:' + s.name;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  };
  for (const s of list) {
    if (!fresh(s)) continue;
    const copy = s.url ? i.copies[s.url] : null;
    const content = copy?.file ? await opfsRead(copy.file) : null;
    if (content == null) { out.push(s); continue; }
    out.push({ ...s, content: content, format: 'turtle', local: true });
  }
  for (const wb of i.workingFiles) {
    if (!fresh({ name: wb.name })) continue;
    out.push({
      name: wb.name, content: (await opfsRead(wb.file)) || '', format: 'turtle', local: true,
    });
  }
  restoreEditSource(i, out);
  return out;
}

function restoreEditSource(i: SourceIndex, out: readonly Source[]): void {
  const target = i.editSource ?? null;
  if (target) {
    const position = out.findIndex((s) => sourceKey(s) === target);
    setEditSourceGraph(position < 0 ? null : String(graphForSource(out[position], position)));
  }
}

async function refreshOpfsContent(list: readonly Source[]): Promise<Source[]> {
  if (!opfsAvailable()) return [...list];
  const rows = enrichSources(list, index(), editSourceGraph());
  const out: Source[] = [];
  for (let i = 0; i < list.length; i++) {
    const file = rows[i]?.opfs;
    const content = file ? await opfsRead(file) : null;
    out.push(content == null ? list[i] : { ...list[i], content: content, format: 'turtle' });
  }
  return out;
}

async function reload(list: Source[]): Promise<void> {
  try {
    await edges.flush();
    const vers = await refreshOpfsContent(list);
    await reloadSources(vers);
  } catch (e) {
    edges.report('src.opfsError', { error: (e as Error).message });
  }
}

export function startSourceManagement(): void {
  registerSourcePreprocessing((list) => withOpfsSources(list));
  setPersistReporter((key: string) => edges.report(key));
  if (opfsAvailable()) setRecoveryBusy(true);
  void loadIndex().then((i) => {
    if (!i.editSource) setRecoveryBusy(false);
  });
  if (typeof setTimeout === 'function') setTimeout(safetyNetClosesRecovery, RECOVERY_DEADLINE_MS);
}

// Looks at the WORK, not at the clock: closing on the timer while the OPFS read
// is still running makes the mutation core judge on an edit source that does not
// exist yet, and a cancel click in that window leaves the app in read mode for
// good. Returns false when it held back, so this is testable without a clock.
export function safetyNetClosesRecovery(): boolean {
  if (recoveryRunning) return false;
  setRecoveryBusy(false);
  return true;
}
