// THE MOMENT IS THE FEATURE. navigator.storage.persist() asked at page load is
// refused outright by the heuristic browsers and prompts about work that does
// not exist yet in the permission browsers, so it is asked at the first CONTENT
// write to OPFS and nowhere else. Index bookkeeping does not count as work.
let attempt = null;
let report = null;

export function setPersistReporter(fn) { report = fn || null; }

export function _resetPersistForTest() { attempt = null; report = null; }

/** True as soon as the one request is under way — set synchronously. */
export function persistAsked() { return attempt !== null; }

async function run() {
  const store = globalThis.navigator && navigator.storage;
  if (!store || typeof store.persist !== 'function') return null;
  try {
    if (typeof store.persisted === 'function' && await store.persisted()) return true;
    const granted = await store.persist();
    if (!granted && report) report('src.persistDenied');
    return granted;
  } catch {
    // A write may never fail on the storage grant.
    return null;
  }
}

export function askPersistOnce() {
  attempt ??= run();
  return attempt;
}
